#!/bin/bash

# run_all_experiments.sh
# This script runs all Chronos experiment configurations generated by the preparation script.

# Paths
CONFIG_DIR="scripts/traffic_experiment_extended/configs_short"
# Use the venv in the parent directory
PYTHON_BIN="../venv/Scripts/python.exe"

# Fallback for different environments (e.g. Git Bash vs WSL)
if [ ! -f "$PYTHON_BIN" ]; then
    PYTHON_BIN="../venv/bin/python"
fi


# Final check
if [ ! -f "$PYTHON_BIN" ]; then
    echo "Error: Python interpreter not found at ./venv/Scripts/python.exe or ./venv/bin/python"
    echo "Please ensure the virtual environment is installed at the project root."
    exit 1
fi

# Ensure we are in the project root
if [ ! -d "scripts/chronos_experiment" ]; then
    echo "Error: This script must be run from the project root directory."
    exit 1
fi

# Find all YAML configs
CONFIGS=$(ls "$CONFIG_DIR"/*.yaml 2>/dev/null)

if [ -z "$CONFIGS" ]; then
    echo "No configuration files found in $CONFIG_DIR"
    echo "Did you run scripts/prepare_traffic_experiment_2.py first?"
    exit 0
fi

echo "=========================================================="
echo "Starting Chronos Experiment Suite"
echo "=========================================================="

for config in $CONFIGS; do
    echo ""
    echo ">>> Current Experiment: $config"
    echo "----------------------------------------------------------"
    
    # Run the experiment
    "$PYTHON_BIN" -m scripts.chronos_experiment.cli --config "$config"
    
    # Check exit status
    if [ $? -ne 0 ]; then
        echo "!!! Warning: Experiment failed for $config. Continuing to next..."
    else
        echo ">>> Completed $config successfully."
    fi
    echo "----------------------------------------------------------"
done

echo ""
echo "=========================================================="
echo "All experiments complete!"
echo "=========================================================="
